/** Every bundled prefix, as institution code + country code. */
export function bic6Prefixes(): Set<string> {
  const out = new Set<string>();
  for (const line of PACKED) {
    const [country, ...codes] = line.split(" ");
    for (const code of codes) out.add(code + country);
  }
  return out;
}
